const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const chiangMai = ee.Geometry.Point(98.987, 18.788); // Chiang Mai, Thailand
  const bangkok = ee.Geometry.Point(100.5, 13.75);     // Bangkok, Thailand
  const startDate = '2024-03-01';
  const endDate = '2024-03-31';
  const aodBand = 'aerosol_optical_thickness_550nm';
  const qaBand = 'qa_value';
  const scale = 1113.2; // S5P nominal resolution is ~5.5km x 3.5km, using a safe scale.

  // 2. Data Acquisition & Check
  const s5pCollection = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_AER_LH')
    .filterDate(startDate, endDate)
    .select([aodBand, qaBand]);

  // Function to process AOD for a given location
  const getAodStats = async (location, name) => {
    let collection = s5pCollection.filterBounds(location);

    const initialSize = await collection.size().getInfo();
    if (initialSize === 0) {
      console.log(`Initial images for ${name}: 0`);
      return { mean: null, pixels: 0, images: 0, status: 'C1' };
    }
    console.log(`Initial images for ${name}: ${initialSize}`);

    // Apply QA filter
    collection = collection.filter(ee.Filter.gt(qaBand, 0.75));

    const qaFilteredSize = await collection.size().getInfo();
    if (qaFilteredSize === 0) {
      console.log(`QA filtered images for ${name}: 0`);
      return { mean: null, pixels: 0, images: 0, status: 'C2' };
    }

    // Calculate the mean image over the period
    const meanImage = collection.mean();

    // Reduce region to get the mean AOD value
    const stats = await meanImage.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: location,
      scale: scale,
      maxPixels: 1e9
    }).get(aodBand).getInfo();

    // Get pixel count for validation
    const pixelCount = await meanImage.select(aodBand).reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: location,
      scale: scale,
      maxPixels: 1e9
    }).get(aodBand).getInfo();

    return { mean: stats, pixels: pixelCount, images: qaFilteredSize, status: 'OK' };
  };

  const cmStats = await getAodStats(chiangMai, 'Chiang Mai');
  const bkStats = await getAodStats(bangkok, 'Bangkok');

  // Handle C1/C2 cases
  if (cmStats.status === 'C1' || bkStats.status === 'C1') {
    console.log("Empty Collection (No images found in date/location for one or both comparison points).");
    console.log("C1");
    return;
  }
  if (cmStats.status === 'C2' || bkStats.status === 'C2') {
    console.log("No Valid Pixels (Images exist, but after QA masking, 0 pixels remain).");
    console.log("C2");
    return;
  }

  // 4. Calculation & Validation
  const chiangMaiAOD = cmStats.mean;
  const bangkokAOD = bkStats.mean;

  console.log(`Chiang Mai AOD: ${chiangMaiAOD !== null ? chiangMaiAOD.toFixed(3) : 'N/A'}, Images: ${cmStats.images}, Valid Pixels: ${cmStats.pixels}`);
  console.log(`Bangkok AOD: ${bangkokAOD !== null ? bangkokAOD.toFixed(3) : 'N/A'}, Images: ${bkStats.images}, Valid Pixels: ${bkStats.pixels}`);

  if (chiangMaiAOD === null || bangkokAOD === null || isNaN(chiangMaiAOD) || isNaN(bangkokAOD)) {
    console.log("Calculation Failure (Result is None, NaN, or invalid).");
    console.log("C3");
  } else if (chiangMaiAOD > bangkokAOD) {
    console.log("A"); // Yes, Chiang Mai AOD was higher
  } else {
    console.log("B"); // No, Chiang Mai AOD was not higher (it was equal or lower)
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
